package com.careerconnect.jobportal.controller;
import com.careerconnect.jobportal.repository.JobRepository; import java.time.LocalDate; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller public class JobController {private final JobRepository jobs;public JobController(JobRepository jobs){this.jobs=jobs;}@GetMapping("/jobs")public String jobs(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String location,Model m){m.addAttribute("jobs",jobs.searchActiveJobs(LocalDate.now(),q.trim(),location.trim()));m.addAttribute("q",q);m.addAttribute("location",location);return "jobs";}@GetMapping("/jobs/{id}")public String job(@PathVariable Long id,Model m){m.addAttribute("job",jobs.findById(id).orElseThrow());return "job-detail";}}
